<?php
namespace App\Http\Controllers;
use App\Models\{FinancialExpense as Expense,ExpensePayment as Payment,ExpenseEvent as Event,Company,User};
use App\Support\{Finance,TreatmentPlan,Expenses};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\{Rule,ValidationException};
class ExpenseController extends Controller {
 private function authorize(Request $r):void{abort_unless($r->user()->active&&($r->user()->isOwner()||$r->user()->isReception()),403);}
 private function lock(Request $r):void{Company::whereKey($r->user()->company_id)->lockForUpdate()->firstOrFail();$u=User::whereKey($r->user()->id)->lockForUpdate()->firstOrFail();abort_unless($u->active&&$u->company_id===$r->user()->company_id&&($u->isOwner()||$u->isReception()),403);}
 private function today(Request $r):string{return app(\App\Services\Availability::class)->localNow($r->user()->company)->toDateString();}
 private function expense(Request $r,int $id):Expense{return Expense::where('company_id',$r->user()->company_id)->findOrFail($id);}
 private function fail(string $key,string $text):never{throw ValidationException::withMessages([$key=>$text]);}
 private function view(string $name,array $data){return response()->view('expenses.'.$name,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 private function event(Request $r,Expense $e,string $event,array $payload=[]):void{Event::create(['company_id'=>$e->company_id,'expense_id'=>$e->id,'actor_id'=>$r->user()->id,'event'=>$event,'payload'=>$payload]);}
 private function fields(Request $r):array{$d=$r->validate(['description'=>'required|string|max:500','supplier'=>'nullable|string|max:150','category'=>['required',Rule::in(array_keys(Expenses::CATEGORIES))],'due_on'=>'required|date_format:Y-m-d|after_or_equal:1900-01-01|before_or_equal:2100-01-01','amount'=>['required','regex:/^\d{1,10}([.,]\d{1,2})?$/']]);$d['amount_cents']=TreatmentPlan::cents($d['amount']);unset($d['amount']);if($d['amount_cents']<1)$this->fail('amount','O valor deve ser maior que zero.');return $d;}
 public function index(Request $r){$this->authorize($r);$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d','status'=>['nullable',Rule::in(array_keys(Expenses::STATES))],'category'=>['nullable',Rule::in(array_keys(Expenses::CATEGORIES))]]);$today=$this->today($r);$from=$r->input('from')?:substr($today,0,7).'-01';$to=$r->input('to')?:\Carbon\Carbon::parse($today)->endOfMonth()->toDateString();if($from>$to)$this->fail('to','O fim do período deve ser igual ou posterior ao início.');$q=Expense::where('company_id',$r->user()->company_id)->whereDate('due_on','>=',$from)->whereDate('due_on','<=',$to)->when($r->filled('category'),fn($q)=>$q->where('category',$r->input('category')));
  $paidSql='(SELECT COALESCE(SUM(amount_cents),0) FROM expense_payments WHERE expense_id=financial_expenses.id AND reversed_at IS NULL)';
  $rows=(clone $q)->where('status','active')->select('financial_expenses.*')->selectRaw($paidSql.' AS paid_cents');$stats=DB::query()->fromSub($rows->toBase(),'totals')->selectRaw('COALESCE(SUM(amount_cents-paid_cents),0) AS pending')->selectRaw('COALESCE(SUM(CASE WHEN due_on < ? THEN amount_cents-paid_cents ELSE 0 END),0) AS overdue',[$today])->first();
  $state=$r->input('status','all');if($state==='cancelled')$q->where('status','cancelled');elseif(in_array($state,['open','paid']))$q->where('status','active')->whereRaw($paidSql.($state==='open'?' < ':' >= ').'amount_cents');
  $expenses=$q->select('financial_expenses.*')->selectRaw($paidSql.' AS paid_cents')->orderBy('due_on')->orderBy('id')->paginate(20)->withQueryString();return $this->view('index',compact('expenses','stats','today','from','to'));
 }
 public function create(Request $r){$this->authorize($r);$expense=null;$today=$this->today($r);return $this->view('form',compact('expense','today'));}
 public function store(Request $r){$this->authorize($r);$r->validate(['request_id'=>'required|uuid']);$d=$this->fields($r);$id=DB::transaction(function()use($r,$d){$this->lock($r);$key=hash('sha256','expense|'.$r->user()->company_id.'|'.$r->user()->id.'|'.$r->input('request_id'));if($e=Expense::where('request_key',$key)->first())return $e->id;$e=Expense::create($d+['company_id'=>$r->user()->company_id,'created_by'=>$r->user()->id,'request_key'=>$key]);$this->event($r,$e,'created',$d);return $e->id;},3);return redirect()->route('expenses.show',$id)->with('success','Despesa cadastrada. Registre o pagamento quando realizado.');}
 public function show(Request $r,int $id){$this->authorize($r);$company=(int)$r->user()->company_id;$expense=$this->expense($r,$id)->load(['payments'=>fn($q)=>$q->where('company_id',$company),'payments.creator'=>fn($q)=>$q->where('company_id',$company),'events'=>fn($q)=>$q->where('company_id',$company),'events.actor'=>fn($q)=>$q->where('company_id',$company)]);$today=$this->today($r);return $this->view('show',compact('expense','today'));}
 public function edit(Request $r,int $id){$this->authorize($r);$expense=$this->expense($r,$id);abort_unless($expense->status==='active'&&!$expense->validPayments()->exists(),422,'Só é possível revisar despesas sem pagamentos válidos.');$today=$this->today($r);return $this->view('form',compact('expense','today'));}
 public function update(Request $r,int $id){$this->authorize($r);$r->validate(['revision'=>'required|integer']);$d=$this->fields($r);DB::transaction(function()use($r,$id,$d){$this->lock($r);$e=$this->expense($r,$id);if($e->status!=='active'||$e->revision!==$r->integer('revision')||$e->validPayments()->exists())$this->fail('revision','A despesa mudou ou tem pagamentos válidos. Reabra a página.');$e->update($d+['revision'=>$e->revision+1]);$this->event($r,$e,'updated',$d);},3);return redirect()->route('expenses.show',$id)->with('success','Despesa revisada.');}
 public function pay(Request $r,int $id){$this->authorize($r);$d=$r->validate(['request_id'=>'required|uuid','amount'=>['required','regex:/^\d{1,10}([.,]\d{1,2})?$/'],'paid_on'=>'required|date_format:Y-m-d|after_or_equal:1900-01-01|before_or_equal:'.$this->today($r),'method'=>['required',Rule::in(array_keys(Finance::METHODS))],'acknowledge'=>'accepted']);DB::transaction(function()use($r,$id,$d){$this->lock($r);$e=$this->expense($r,$id);$key=hash('sha256','expense-payment|'.$e->company_id.'|'.$r->user()->id.'|'.$d['request_id']);if($p=Payment::where('request_key',$key)->first()){abort_unless($p->expense_id===$id,409);return;}abort_unless($e->status==='active',422,'Despesa cancelada não aceita pagamentos.');$amount=TreatmentPlan::cents($d['amount']);if($amount<1||$amount>$e->balanceCents())$this->fail('amount','Informe um valor positivo até o saldo atual da despesa.');$p=$e->payments()->create(['company_id'=>$e->company_id,'created_by'=>$r->user()->id,'amount_cents'=>$amount,'paid_on'=>$d['paid_on'],'method'=>$d['method'],'request_key'=>$key]);$e->increment('revision');$this->event($r,$e,'paid',['payment_id'=>$p->id,'amount_cents'=>$amount,'paid_on'=>$d['paid_on'],'method'=>$d['method']]);},3);return back()->with('success','Pagamento de despesa registrado.');}
 public function reverse(Request $r,int $id){$this->authorize($r);abort_unless($r->user()->isOwner(),403);$d=$r->validate(['reason'=>'required|string|min:5|max:500']);$eid=DB::transaction(function()use($r,$id,$d){$this->lock($r);abort_unless(User::findOrFail($r->user()->id)->isOwner(),403);$p=Payment::forCompany((int)$r->user()->company_id)->findOrFail($id);$e=Expense::forCompany((int)$p->company_id)->findOrFail($p->expense_id);if(!$p->reversed_at){$p->update(['reversed_at'=>now(),'reversed_by'=>$r->user()->id,'reversal_reason'=>$d['reason']]);$e->increment('revision');$this->event($r,$e,'reversed',['payment_id'=>$p->id,'amount_cents'=>$p->amount_cents,'reason'=>$d['reason']]);}return $e->id;},3);return redirect()->route('expenses.show',$eid)->with('success','Lançamento estornado e saldo reaberto. Não houve movimentação bancária.');}
 public function cancel(Request $r,int $id){$this->authorize($r);$d=$r->validate(['revision'=>'required|integer','reason'=>'required|string|min:5|max:500']);DB::transaction(function()use($r,$id,$d){$this->lock($r);$e=$this->expense($r,$id);if($e->status==='cancelled')return;if($e->revision!==(int)$d['revision']||$e->validPayments()->exists())$this->fail('reason','A despesa mudou ou possui pagamentos válidos. Confira os lançamentos antes de cancelar.');$e->update(['status'=>'cancelled','revision'=>$e->revision+1,'cancel_reason'=>$d['reason']]);$this->event($r,$e,'cancelled',['reason'=>$d['reason']]);},3);return back()->with('success','Despesa cancelada. O histórico foi preservado.');}
}
